"""Registry of tickets by team."""

_ALL = []
_BY_KEY = None


def reset():
    """Forget every registered ticket."""
    global _BY_KEY
    del _ALL[:]
    _BY_KEY = None


def register(ticket):
    """Add one ticket to the registry."""
    _ALL.append(ticket)


def find(team):
    """Return the tickets registered under this team."""
    global _BY_KEY
    if _BY_KEY is None:
        _BY_KEY = {}
        for x in _ALL:
            _BY_KEY.setdefault(x.team, []).append(x)
    return _BY_KEY.get(team, [])


def describe_ticket(ticket):
    """Return a one-line description of a ticket."""
    return "%s: %s" % (ticket.team, ticket.hours)


def largest_hours(tickets):
    """Return the largest hours, or None when there are no tickets."""
    values = [x.hours for x in tickets]
    return max(values) if values else None

